function resultStats(k,snapshot){const intrinsic=typeof k==='string'?window.getAbyssIntrinsicCardStats?.(k):null,live=typeof k==='string'?window.getAbyssCardStats?.(k):null,raw=typeof k==='string'?window.getAbyssCardData?.(k):null;return Object.assign({},raw||{},live||{},intrinsic||{},snapshot||{})}
function resultEntry(r){const before=resultStats(r.before,r.beforeStats),after=r.after?resultStats(r.after,r.afterStats):null,c=after||before,labels={upgrade:'強化',remove:'削除',duplicate:'複製',gain:'獲得'},key=r.after||r.before,effect=r.kind==='upgrade'?window.renderAbyssUpgradeComparison(r.before,'result-upgrade-compare'):'';return `<article class="multi-result-card unified-result-card"><b>${labels[r.kind]||'変更'}：${before.n||c.n||r.before||''}</b>${window.renderAbyssCardView?.(key)||''}${effect}</article>`}
