window.openAbyssDeckSelection=({title,text,count=1,filter=()=>true,preview=null,action})=>{const g=game(),cards=g.deck.map((k,i)=>({k,i})).filter(x=>filter(x.k,x.i)),needed=Math.min(Math.max(0,count),cards.length),selected=new Set();window.__abyssEventDeferred=true;multiChoice.querySelector('#multiDeckTitle').textContent=title;multiChoice.querySelector('#multiDeckText').textContent=text;const list=multiChoice.querySelector('#multiDeckList'),counter=multiChoice.querySelector('#multiDeckCount'),confirm=multiChoice.querySelector('#multiDeckConfirm');list.innerHTML=cards.map(x=>deckEntry(x.k,x.i)).join('')||'<p>選べるカードがありません。</p>';const sync=()=>{counter.textContent=`${selected.size} / ${needed}枚 選択`;confirm.disabled=selected.size!==needed;list.querySelectorAll('button').forEach(b=>{const i=+b.dataset.index,on=selected.has(i);b.classList.toggle('selected',on);b.querySelector('.selection-upgrade-preview')?.remove();if(on&&preview)b.insertAdjacentHTML('beforeend',preview(g.deck[i]))})};list.querySelectorAll('button').forEach(b=>b.onclick=()=>{const i=+b.dataset.index;if(selected.has(i))selected.delete(i);else if(selected.size<needed)selected.add(i);sync();window.applyFuri?.(list)});confirm.onclick=()=>{if(selected.size!==needed)return;const picks=[...selected].map(i=>{const key=g.deck[i];return{index:i,key,stats:resultStats(key)}}),results=action?.(picks,g)||[];multiChoice.classList.remove('on');window.showAbyssDeckResults?.(title,results,()=>{window.__abyssEventDeferred=false;window.abyssSave?.();window.abyssAdvance?.()})};multiChoice.classList.add('on');sync();if(!needed)confirm.disabled=false;window.applyFuri?.(multiChoice)};
